## Federation (Decorator Pattern)

### FederationGateway

```typescript
/**
 * Peer system connection.
 */
interface PeerConnection {
  systemId: string;
  endpoint: string;
  status: 'connected' | 'disconnected' | 'connecting';
  connectedAt?: number;
  lastActivity?: number;
}

/**
 * Federation envelope for cross-system messages.
 */
interface FederationEnvelope {
  /** Original message */
  payload: unknown;
  /** Routing metadata */
  routing: {
    from: string;
    to: string;
    hops: string[];
    maxHops: number;
  };
  /** Timestamp */
  timestamp: number;
}

/**
 * Gateway for federation between MAP systems.
 */
interface FederationGateway {
  /** Connect to a peer system */
  connectPeer(params: {
    systemId: string;
    endpoint: string;
    credentials?: unknown;
  }): Promise<PeerConnection>;

  /** Route message to peer */
  routeToPeer(systemId: string, envelope: FederationEnvelope): Promise<void>;

  /** Handle incoming messages from peers */
  onPeerMessage(handler: (from: string, envelope: FederationEnvelope) => void): void;

  /** List connected peers */
  listPeers(): PeerConnection[];

  /** Disconnect from peer */
  disconnectPeer(systemId: string): void;

  /** Outage buffer for resilience */
  readonly buffer: OutageBuffer;
}

/**
 * Buffers messages during peer outages.
 */
interface OutageBuffer {
  /** Add message to buffer */
  add(systemId: string, envelope: FederationEnvelope): void;

  /** Flush buffered messages (on reconnect) */
  flush(systemId: string): FederationEnvelope[];

  /** Get buffer stats */
  stats(): { total: number; bySystem: Record<string, number> };
}
```

