## Usage Examples

### Minimal Server (In-Memory)

```typescript
import {
  EventBus,
  AgentRegistry,
  ScopeManager,
  SessionManager,
  SubscriptionManager,
  MessageRouter,
  RouterConnection,
  createAgentHandlers,
  createScopeHandlers,
  createSubscriptionHandlers,
  createMessageHandlers,
  createConnectionHandlers,
} from '@anthropic/multi-agent-protocol/server';

// Create building blocks with defaults
const eventBus = new EventBus();
const sessions = new SessionManager({ eventBus });
const agents = new AgentRegistry({ eventBus });
const scopes = new ScopeManager({ eventBus });
const subscriptions = new SubscriptionManager({ eventBus, scopes });
const messages = new MessageRouter({ eventBus, agents, scopes });

// Wire up handlers
const handlers = {
  ...createConnectionHandlers({ sessions }),
  ...createAgentHandlers({ agents, sessions }),
  ...createScopeHandlers({ scopes, agents }),
  ...createSubscriptionHandlers({ subscriptions, eventBus }),
  ...createMessageHandlers({ messages }),
};

// Create router for each connection
function handleConnection(stream: Stream) {
  const router = new RouterConnection(stream, {
    handlers,
    sessions,
    role: 'agent',
  });
  router.start();
}
```

### With OOP Interface

```typescript
import { BaseMAPRouter, routerToHandlers } from '@anthropic/multi-agent-protocol/server';

class MyRouter extends BaseMAPRouter {
  // Override specific methods
  async registerAgent(params, ctx) {
    // Custom logic before registration
    console.log(`Registering agent: ${params.name}`);

    // Call default implementation
    const agent = await super.registerAgent(params, ctx);

    // Custom logic after registration
    await this.notifyAdmins(agent);

    return agent;
  }
}

const router = new MyRouter({ agents, scopes, sessions, subscriptions, messages, eventBus });
const connection = new RouterConnection(stream, {
  handlers: routerToHandlers(router),
  sessions,
  role: 'agent',
});
```

### With Session Resume

```typescript
function handleConnection(stream: Stream, resumeToken?: string) {
  const router = new RouterConnection(stream, {
    handlers,
    sessions,
    role: 'agent',
    resumeToken, // Pass token from client's reconnect request
  });

  router.start().then(() => {
    if (resumeToken) {
      // Flush any queued messages
      const agentIds = router.session.agentIds;
      for (const agentId of agentIds) {
        messages.flushQueue(agentId);
      }
    }
  });
}
```

### With Cleanup

```typescript
import { ResourceCleaner } from '@anthropic/multi-agent-protocol/server';

const cleaner = new ResourceCleaner({
  sessions,
  agents,
  subscriptions,
  messages,
  thresholds: {
    sessionDisconnectMs: 5 * 60 * 1000, // 5 minutes
    sessionInactiveMs: 30 * 60 * 1000,  // 30 minutes
    intervalMs: 60 * 1000,               // Run every minute
  },
  strategy: {
    onStaleSession(session) {
      console.log(`Cleaning up stale session: ${session.id}`);
    },
  },
});

// Start automatic cleanup
cleaner.start();

// Or run manually
const stats = await cleaner.run();
console.log(`Cleaned: ${stats.sessionsExpired} sessions, ${stats.agentsUnregistered} agents`);
```

